Card::new().body(Text::muted(
    "A card with no header holds anything: a form, a table, a chart.",
))

[
    ("Right", SheetSide::Right),
    ("Left", SheetSide::Left),
    ("Top", SheetSide::Top),
    ("Bottom", SheetSide::Bottom),
]
.map(|(name, side)| {
    let id = format!("sheet-{}", name.to_lowercase());
    let open = Button::outline("Open").opens_dialog(id.clone());
    let sheet = Sheet::new(id, format!("From the {}", name.to_lowercase()))
        .side(side)
        .body(Text::muted("Press Esc or click outside to close."));
    (name, Node::list((open, sheet)))
})

[
    Justify::Start,
    Justify::Center,
    Justify::End,
    Justify::Between,
]
.map(|justify| {
    let name = match justify {
        Justify::Start => "Justify::Start",
        Justify::Center => "Justify::Center",
        Justify::End => "Justify::End",
        _ => "Justify::Between",
    };
    (
        name,
        Row::gap(2).justify(justify).children((
            Badge::new("One"),
            Badge::new("Two"),
            Badge::new("Three"),
        )),
    )
})

let query = TableQuery::<Deal>::parse("/deals", "");
let rows: Vec<Deal> = deals().into_iter().take(2).collect();
DataTable::new("deals", &query, &rows).into()

let query = TableQuery::<Deal>::parse("/deals", "");
let page = TablePage::new(deals(), 128);
DataTable::new("deals", &query, &page)
    .caption("Deals")
    .export("/deals/export")
    .into()

let query = TableQuery::<Deal>::parse("/deals", "");
let page = TablePage::new(deals(), 128);
DataTable::new("deals", &query, &page)
    .caption("Deals")
    .bulk(
        "/deals/bulk",
        [
            BulkAction::new("archive", "Archive").icon(icons::ARCHIVE),
            BulkAction::new("delete", "Delete")
                .destructive()
                .confirm("Delete {n} deals?"),
        ],
    )
    .row_actions(|deal| {
        vec![
            RowAction::link("Open", format!("/deals/{}", deal.id)),
            RowAction::post("Archive", format!("/deals/{}/archive", deal.id)),
        ]
    })
    .into()

let query = TableQuery::<Deal>::parse("/deals", "f.amount.min=500000");
let page = TablePage::new(deals(), 4);
DataTable::new("deals", &query, &page)
    .caption("Deals")
    .filter_row()
    .into()

let query = TableQuery::<Deal>::parse("/deals", "density=compact");
let page = TablePage::new(deals(), 5);
DataTable::new("deals", &query, &page)
    .caption("Deals")
    .into()

